<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;

Auth::requirePermission('tables.manage');$tenantId=em_require_tenant();
$uq=$pdo->prepare('SELECT id,name,active FROM operating_units WHERE tenant_id=? ORDER BY active DESC,name');$uq->execute([$tenantId]);$units=$uq->fetchAll();$activeUnitIds=array_map('intval',array_column(array_filter($units,fn($u)=>(int)$u['active']===1),'id'));
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    if($action==='table-save'){
        $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$seats=max(1,(int)($_POST['seats']??4));$status=(string)($_POST['status']??'available');$unitId=(int)($_POST['unit_id']??0);$unitId=$unitId>0?$unitId:null;
        if($name===''||!in_array($status,['available','occupied','inactive'],true))exit('Mesa inválida.');if($units&&$unitId===null)exit('Selecione a unidade da mesa.');if($unitId!==null&&!in_array($unitId,$activeUnitIds,true))exit('Unidade inválida ou inativa.');
        try{
            Database::transaction(function(PDO $tx)use(&$id,$tenantId,$name,$seats,$status,$unitId):void{
                if($id){
                    $q=$tx->prepare(Database::portableSql($tx,'SELECT id,unit_id,status FROM restaurant_tables WHERE id=? AND tenant_id=? FOR UPDATE'));$q->execute([$id,$tenantId]);$current=$q->fetch();if(!$current)throw new RuntimeException('Mesa não encontrada.');
                    $oldUnit=$current['unit_id']!==null?(int)$current['unit_id']:null;if($oldUnit!==$unitId){$open=$tx->prepare('SELECT COUNT(*) FROM tabs WHERE tenant_id=? AND table_id=? AND status="open"');$open->execute([$tenantId,$id]);if((int)$open->fetchColumn()>0)throw new RuntimeException('Encerre a comanda antes de mover esta mesa para outra unidade.');}
                    $s=$tx->prepare('UPDATE restaurant_tables SET unit_id=?,name=?,seats=?,status=? WHERE id=? AND tenant_id=?');$s->execute([$unitId,$name,$seats,$status,$id,$tenantId]);
                }else{
                    $s=$tx->prepare('INSERT INTO restaurant_tables (tenant_id,unit_id,name,seats,status,qr_token) VALUES (?,?,?, ?,"available",?)');$s->execute([$tenantId,$unitId,$name,$seats,bin2hex(random_bytes(20))]);$id=(int)$tx->lastInsertId();
                }
            });
            Auth::audit('table.saved','table',(string)$id,['unit_id'=>$unitId]);em_flash('ok','Mesa salva.');
        }catch(Throwable $e){em_flash('error',$e->getMessage());}
        em_go('restaurant');
    }
    if($action==='tab-open'){
        $tableId=(int)($_POST['table_id']??0);$label=trim((string)($_POST['label']??''));
        try{$id=Database::transaction(function(PDO $tx)use($tableId,$tenantId,$label):int{$t=$tx->prepare(Database::portableSql($tx,'SELECT id,status,unit_id FROM restaurant_tables WHERE id=? AND tenant_id=? FOR UPDATE'));$t->execute([$tableId,$tenantId]);$table=$t->fetch();if(!$table||$table['status']==='inactive')throw new RuntimeException('Mesa indisponível.');$open=$tx->prepare('SELECT id FROM tabs WHERE tenant_id=? AND table_id=? AND status="open"');$open->execute([$tenantId,$tableId]);if($open->fetchColumn())throw new RuntimeException('A mesa já possui comanda aberta.');$s=$tx->prepare('INSERT INTO tabs (tenant_id,table_id,opened_by,label,status) VALUES (?,?,?, ?,"open")');$s->execute([$tenantId,$tableId,Auth::id(),$label?:null]);$id=(int)$tx->lastInsertId();$tx->prepare('UPDATE restaurant_tables SET status="occupied" WHERE id=?')->execute([$tableId]);return $id;});Auth::audit('tab.opened','tab',(string)$id);em_flash('ok','Comanda aberta.');}catch(Throwable $e){em_flash('error',$e->getMessage());}em_go('restaurant');
    }
    if($action==='tab-close'){
        $id=(int)($_POST['id']??0);
        try{$tab=Database::transaction(function(PDO $tx)use($id,$tenantId):array{$s=$tx->prepare(Database::portableSql($tx,'SELECT * FROM tabs WHERE id=? AND tenant_id=? AND status="open" FOR UPDATE'));$s->execute([$id,$tenantId]);$tab=$s->fetch();if(!$tab)throw new RuntimeException('Comanda não encontrada.');$u=$tx->prepare('SELECT COUNT(*) FROM orders WHERE tenant_id=? AND tab_id=? AND status<>"cancelled" AND payment_status<>"paid"');$u->execute([$tenantId,$id]);if((int)$u->fetchColumn()>0)throw new RuntimeException('Existem pedidos não pagos nesta comanda.');$active=$tx->prepare('SELECT COUNT(*) FROM orders WHERE tenant_id=? AND tab_id=? AND status IN ("confirmed","preparing","ready","out_for_delivery")');$active->execute([$tenantId,$id]);if((int)$active->fetchColumn()>0)throw new RuntimeException('Existem pedidos operacionais ainda ativos nesta comanda.');$tx->prepare('UPDATE tabs SET status="closed",closed_by=?,closed_at=CURRENT_TIMESTAMP WHERE id=?')->execute([Auth::id(),$id]);if($tab['table_id'])$tx->prepare('UPDATE restaurant_tables SET status="available" WHERE id=?')->execute([$tab['table_id']]);return $tab;});Auth::audit('tab.closed','tab',(string)$id);em_flash('ok','Comanda encerrada.');}catch(Throwable $e){em_flash('error',$e->getMessage());}em_go('restaurant');
    }
}
$s=$pdo->prepare('SELECT rt.*,ou.name unit_name,tb.id open_tab_id,tb.label,(SELECT COALESCE(SUM(o.total_cents),0) FROM orders o WHERE o.tab_id=tb.id AND o.status<>"cancelled") tab_total,(SELECT COALESCE(SUM(GREATEST(0,o.total_cents-COALESCE((SELECT SUM(p.amount_cents) FROM payments p WHERE p.tenant_id=o.tenant_id AND p.order_id=o.id AND p.status="paid"),0))),0) FROM orders o WHERE o.tab_id=tb.id AND o.status<>"cancelled") unpaid_total FROM restaurant_tables rt LEFT JOIN operating_units ou ON ou.id=rt.unit_id LEFT JOIN tabs tb ON tb.table_id=rt.id AND tb.status="open" WHERE rt.tenant_id=? ORDER BY COALESCE(ou.name,""),rt.name');$s->execute([$tenantId]);$tables=$s->fetchAll();
em_header('Mesas e comandas','restaurant');
?><div class="grid" style="grid-template-columns:minmax(280px,1fr) minmax(0,2fr)"><section class="card"><h2>Nova mesa</h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="table-save"><label>Nome<input name="name" placeholder="Mesa 01" required></label><label>Lugares<input type="number" name="seats" min="1" value="4"></label><?php if($units):?><label class="span-2">Unidade<select name="unit_id" required><option value="">Selecione</option><?php foreach($units as $unit):if(!(int)$unit['active'])continue;?><option value="<?= (int)$unit['id'] ?>"><?= Security::e($unit['name']) ?></option><?php endforeach;?></select></label><?php endif;?><button class="primary span-2">Criar mesa</button></form></section><section class="card"><div class="section-head"><h2>Salão</h2><span class="muted"><?= count($tables) ?> mesas</span></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))"><?php foreach($tables as $t):?><article class="card"><div class="section-head"><h3><?= Security::e($t['name']) ?></h3><span class="badge"><?= Security::e($t['status']) ?></span></div><p class="muted"><?= Security::e($t['unit_name']??'Principal / sem unidade') ?> · <?= (int)$t['seats'] ?> lugares</p><?php if($t['open_tab_id']):?><p><strong>Comanda #<?= (int)$t['open_tab_id'] ?></strong> <?= Security::e($t['label']??'') ?><br>Total: <?= em_money($t['tab_total']) ?><br><span class="muted">Em aberto: <?= em_money($t['unpaid_total']) ?></span></p><form method="post" onsubmit="return confirm('Encerrar esta comanda?')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="tab-close"><input type="hidden" name="id" value="<?= (int)$t['open_tab_id'] ?>"><button class="secondary">Encerrar comanda</button></form><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="tab-open"><input type="hidden" name="table_id" value="<?= (int)$t['id'] ?>"><label>Identificação<input name="label" placeholder="Ex.: João / aniversário"></label><button class="primary" style="margin-top:8px">Abrir comanda</button></form><?php endif;?><details style="margin-top:12px"><summary>Editar mesa</summary><form method="post" class="form-grid" style="margin-top:10px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="table-save"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><label>Nome<input name="name" required value="<?= Security::e($t['name']) ?>"></label><label>Lugares<input type="number" min="1" name="seats" value="<?= (int)$t['seats'] ?>"></label><?php if($units):?><label class="span-2">Unidade<select name="unit_id" required><?php foreach($units as $unit):?><option value="<?= (int)$unit['id'] ?>"<?= em_selected($t['unit_id']??'',(int)$unit['id']) ?><?= !(int)$unit['active']?' disabled':'' ?>><?= Security::e($unit['name']) ?><?= !(int)$unit['active']?' (inativa)':'' ?></option><?php endforeach;?></select></label><?php endif;?><label class="span-2">Status<select name="status"><option value="available"<?= em_selected($t['status'],'available') ?>>Disponível</option><option value="occupied"<?= em_selected($t['status'],'occupied') ?>>Ocupada</option><option value="inactive"<?= em_selected($t['status'],'inactive') ?>>Inativa</option></select></label><button class="secondary span-2">Salvar alterações</button></form></details><p style="margin-top:12px"><a href="<?= Security::e(app_url('mesa.php?t='.urlencode($t['qr_token']))) ?>" target="_blank">Link/QR da mesa</a></p></article><?php endforeach;?></div></section></div><?php em_footer();
